import { sql } from 'drizzle-orm';
import { db } from '@/db';
import { parseSearchParams as p } from '@/lib/search/params';
import { searchCandidates, getFilterOptions } from '@/lib/search/filter-search';
import { GET as searchGET } from '@/app/api/candidates/search/route';
import { GET as filtersGET } from '@/app/api/candidates/filters/route';
import { SKILLS } from '@/lib/derive/skills';
import type { SearchFilters } from '@/lib/contracts';

const E: SearchFilters = { countries: [], skills: [], minYears: null, maxYears: null, minSalary: null, maxSalary: null };
const q = (s: string) => p(new URLSearchParams(s));
const log = (n: number, x: unknown) => console.log(`#${n}`, JSON.stringify(x));
const nonInc = (a: number[]) => a.every((v, i) => i === 0 || a[i - 1] >= v);

async function main() {
  log(1, q(''));
  log(2, q('country=Brazil&country=brazil&country=%20India%20'));
  log(3, q('skill=react&skill=PYTHON'));
  log(4, q('skill=Cobol'));
  log(5, [q('minYears=abc'), q('maxSalary=-1')]);
  log(6, q('minYears=10&maxYears=5'));
  log(7, q('minYears=&maxSalary=120000'));

  let r = await searchCandidates(E);
  log(8, { total: r.total, n: r.results.length, years: r.results.map((x) => x.candidate.yearsExperience), scores: r.results.map((x) => x.score), nonInc: nonInc(r.results.map((x) => x.candidate.yearsExperience)) });
  r = await searchCandidates({ ...E, countries: ['canada'] });
  log(9, { total: r.total, results: r.results });
  r = await searchCandidates({ ...E, countries: ['india'] });
  log(10, { total: r.total, n: r.results.length, allIndia: r.results.every((x) => x.candidate.country === 'India') });
  const rustRows = (await db.all<{ n: number }>(sql`select count(*) as n from candidate_skills where skill = 'Rust'`))[0].n;
  const rust = await searchCandidates({ ...E, skills: ['Rust'] });
  log(11, { total: rust.total, rustRows, ok: rust.results.every((x) => JSON.stringify(x.matchedSkills) === '["Rust"]' && x.reasons.some((y) => y.kind === 'skill' && y.label.startsWith('Rust in'))), reasons: rust.results.map((x) => x.reasons.map((y) => y.label)), scores: rust.results.map((x) => x.score) });
  r = await searchCandidates({ ...E, skills: ['Rust', 'Python'] });
  log(12, { total: r.total, leRust: r.total <= rust.total, ok: r.results.every((x) => JSON.stringify(x.matchedSkills) === '["Rust","Python"]' && x.reasons.filter((y) => y.kind === 'skill').length === 2), reasons: r.results.map((x) => x.reasons.map((y) => y.label)) });
  r = await searchCandidates({ ...E, minYears: 10 });
  log(13, { total: r.total, ok: r.results.every((x) => x.candidate.yearsExperience >= 10 && x.reasons.some((y) => y.label === `${x.candidate.yearsExperience} yrs experience (min 10)`)), sample: r.results.slice(0, 3).map((x) => x.reasons) });
  r = await searchCandidates({ ...E, maxSalary: 60000 });
  log(14, { total: r.total, ok: r.results.every((x) => !x.candidate.rateUnverified && x.candidate.monthlyRate !== null && x.candidate.monthlyRate <= 5000 && x.reasons.some((y) => y.kind === 'salary' && y.label.endsWith('under $60,000'))), sample: r.results.slice(0, 2).map((x) => x.reasons) });
