  const rust = await searchCandidates({ ...E, skills: ['Rust'] });
  log(11, { total: rust.total, rustRows, ok: rust.results.every((x) => JSON.stringify(x.matchedSkills) === '["Rust"]' && x.reasons.some((y) => y.kind === 'skill' && y.label.startsWith('Rust in'))), reasons: rust.results.map((x) => x.reasons.map((y) => y.label)), scores: rust.results.map((x) => x.score) });
  r = await searchCandidates({ ...E, skills: ['Rust', 'Python'] });
  log(12, { total: r.total, leRust: r.total <= rust.total, ok: r.results.every((x) => JSON.stringify(x.matchedSkills) === '["Rust","Python"]' && x.reasons.filter((y) => y.kind === 'skill').length === 2), reasons: r.results.map((x) => x.reasons.map((y) => y.label)) });
  r = await searchCandidates({ ...E, minYears: 10 });
  log(13, { total: r.total, ok: r.results.every((x) => x.candidate.yearsExperience >= 10 && x.reasons.some((y) => y.label === `${x.candidate.yearsExperience} yrs experience (min 10)`)), sample: r.results.slice(0, 3).map((x) => x.reasons) });
  r = await searchCandidates({ ...E, maxSalary: 60000 });
  log(14, { total: r.total, ok: r.results.every((x) => !x.candidate.rateUnverified && x.candidate.monthlyRate !== null && x.candidate.monthlyRate <= 5000 && x.reasons.some((y) => y.kind === 'salary' && y.label.endsWith('under $60,000'))), sample: r.results.slice(0, 2).map((x) => x.reasons) });
  for (const f of [E, { ...E, skills: ['React'] }, { ...E, skills: ['Python', 'AWS'], countries: ['Brazil'] }, { ...E, countries: ['canada'] }]) {
    r = await searchCandidates(f);
    log(15, { f: f.skills, total: r.total, n: r.results.length, ok: nonInc(r.results.map((x) => x.score)) && r.results.length <= 10 && r.results.length <= r.total, scores: r.results.map((x) => x.score) });
  }
  const o = await getFilterOptions();
  log(16, { first: o.countries[0], dash: o.countries.some((c) => c.name === '-'), allSkills: o.skills.every((s) => SKILLS.includes(s.name)), countries: o.countries, skills: o.skills.slice(0, 5), nSkills: o.skills.length });

  let res = await searchGET(new Request('http://localhost/api/candidates/search?skill=react'));
  let body = await res.json();
  log(17, { status: res.status, skills: body.filters.skills, total: body.total });
  res = await searchGET(new Request('http://localhost/api/candidates/search?skill=Cobol'));
  log(18, { status: res.status, body: await res.json() });
  res = await filtersGET();
  body = await res.json();
  log(19, { status: res.status, c: body.countries.length, s: body.skills.length });

  // extra: both ranges, min salary
  r = await searchCandidates({ ...E, minYears: 3, maxYears: 5, minSalary: 50000, maxSalary: 100000 });
  log(0, { total: r.total, reasons: r.results.slice(0, 2).map((x) => x.reasons) });
  r = await searchCandidates({ ...E, minSalary: 200000 });
  log(0, { total: r.total, reasons: r.results.slice(0, 2).map((x) => x.reasons) });

  res = await searchGET(new Request('http://localhost/api/candidates/search?skill=react&country=brazil&minYears=5'));
  console.log('SAMPLE', JSON.stringify(await res.json(), null, 2));
}
main();

